import{_ as r,a0 as l,w as d,s as c,ao as s,I as a,a1 as o,A as n,x as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"如何在  Linux/Unix 中不重啓 Vim 而重新加載 .vimrc 文件 | LCTT x X-CMD","titleTemplate":false,"description":"如何在  Linux/Unix 中不重啓 Vim 而重新加載 .vimrc 文件 | LCTT (201802) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在  Linux/Unix 中不重啓 Vim 而重新加載 .vimrc 文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在  Linux/Unix 中不重啓 Vim 而重新加載 .vimrc 文件 | LCTT (201802) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201802/20180201 How to reload .vimrc file without restarting vim on Linux-Unix","title":"如何在  Linux/Unix 中不重啓 Vim 而重新加載 .vimrc 文件","tag":"201802","desc":""},"relativePath":"201802/20180201 How to reload .vimrc file without restarting vim on Linux-Unix.md","filePath":"[post].md"}'),p={name:"201802/20180201 How to reload .vimrc file without restarting vim on Linux-Unix.md"};function m(u,i,v,f,g,x){const t=l("Link");return d(),c("div",null,[i[17]||(i[17]=s(`<h1 id="如何在-linux-unix-中不重啓-vim-而重新加載-vimrc-文件" tabindex="-1">如何在 Linux/Unix 中不重啓 Vim 而重新加載 .vimrc 文件 <a class="header-anchor" href="#如何在-linux-unix-中不重啓-vim-而重新加載-vimrc-文件" aria-label="Permalink to “如何在  Linux/Unix 中不重啓 Vim 而重新加載 .vimrc 文件”">​</a></h1><p>我是一位新的 Vim 編輯器用户。我通常使用 <code>:vs ~/.vimrc</code> 來加載 <code>~/.vimrc</code> 配置。而當我編輯 <code>.vimrc</code> 時，我需要不重啓 Vim 會話而重新加載它。在 Linux 或者類 Unix 系統中，如何在編輯 <code>.vimrc</code> 後，重新加載它而不用重啓 Vim 呢？</p><p>Vim 是自由開源並且向上兼容 Vi 的編輯器。它可以用來編輯各種文本。它在編輯用 C/Perl/Python 編寫的程序時特別有用。可以用它來編輯 Linux/Unix 配置文件。<code>~/.vimrc</code> 是你個人的 Vim 初始化和自定義文件。</p><h3 id="如何在不重啓-vim-會話的情況下重新加載-vimrc" tabindex="-1">如何在不重啓 Vim 會話的情況下重新加載 .vimrc <a class="header-anchor" href="#如何在不重啓-vim-會話的情況下重新加載-vimrc" aria-label="Permalink to “如何在不重啓 Vim 會話的情況下重新加載 .vimrc”">​</a></h3><p>在 Vim 中重新加載 <code>.vimrc</code> 而不重新啓動的流程：</p><ol><li>輸入 <code>vim filename</code> 啓動 vim</li><li>按下 <code>Esc</code> 接着輸入 <code>:vs ~/.vimrc</code> 來加載 vim 配置</li><li>像這樣添加自定義配置：</li></ol><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>filetype indent plugin on</span></span>
<span class="line"><span>set number</span></span>
<span class="line"><span>syntax on</span></span></code></pre></div><ol start="4"><li>使用 <code>:wq</code> 保存文件，並從 <code>~/.vimrc</code> 窗口退出</li><li>輸入下面任一命令重載 <code>~/.vimrc</code>：<code>:so $MYVIMRC</code> 或者 <code>:source ~/.vimrc</code>。</li></ol>`,8)),a("p",null,[o(t,{href:"https://www.cyberciti.biz/media/new/faq/2018/02/How-to-reload-.vimrc-file-without-restarting-vim.jpg"},{default:n(()=>[...i[0]||(i[0]=[a("img",{src:"https://www.cyberciti.biz/media/new/faq/2018/02/How-to-reload-.vimrc-file-without-restarting-vim.jpg",alt:"How to reload .vimrc file without restarting vim"},null,-1)])]),_:1})]),i[18]||(i[18]=s(`<p><em>圖1：編輯 ~/.vimrc 並在需要時重載它而不用退出 vim，這樣你就可以繼續編輯程序了</em></p><p><code>:so[urce]! {file}</code> 這個 vim 命令會從給定的文件比如 <code>~/.vimrc</code> 讀取配置。就像你輸入的一樣，這些命令是在普通模式下執行的。當你在 <code>:global</code>、:<code>argdo</code>、 <code>:windo</code>、<code>:bufdo</code> 之後、循環中或者跟着另一個命令時，顯示不會再在執行命令時更新。</p><h3 id="如何設置按鍵來編輯並重載-vimrc" tabindex="-1">如何設置按鍵來編輯並重載 ~/.vimrc <a class="header-anchor" href="#如何設置按鍵來編輯並重載-vimrc" aria-label="Permalink to “如何設置按鍵來編輯並重載 ~/.vimrc”">​</a></h3><p>在你的 <code>~/.vimrc</code> 後面跟上這些：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&quot; Edit vimr configuration file</span></span>
<span class="line"><span>nnoremap confe :e $MYVIMRC&lt;CR&gt;</span></span>
<span class="line"><span>&quot; Reload vims configuration file</span></span>
<span class="line"><span>nnoremap confr :source $MYVIMRC&lt;CR&gt;</span></span></code></pre></div><p>現在只要按下 <code>Esc</code> 接着輸入 <code>confe</code> 就可以編輯 <code>~/.vimrc</code>。按下 <code>Esc</code> ，接着輸入 <code>confr</code> 以重新加載。一些人喜歡在 <code>.vimrc</code> 中使用 <code>&lt;Leader&gt;</code> 鍵。因此上面的映射變成：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&quot; Edit vimr configuration file</span></span>
<span class="line"><span>nnoremap &lt;Leader&gt;ve :e $MYVIMRC&lt;CR&gt;</span></span>
<span class="line"><span>&quot; Reload vimr configuration file</span></span>
<span class="line"><span>nnoremap &lt;Leader&gt;vr :source $MYVIMRC&lt;CR&gt;</span></span></code></pre></div><p><code>&lt;Leader&gt;</code> 鍵默認映射成 <code>\\</code> 鍵。因此只要輸入 <code>\\</code> 接着 <code>ve</code> 就能編輯文件。按下 <code>\\</code> 接着 <code>vr</code> 就能重載 <code>~/vimrc</code>。</p><p>這就完成了，你可以不用再重啓 Vim 就能重新加載 <code>.vimrc</code> 了。</p><h3 id="關於作者" tabindex="-1">關於作者 <a class="header-anchor" href="#關於作者" aria-label="Permalink to “關於作者”">​</a></h3>`,10)),a("p",null,[i[2]||(i[2]=e("作者是 nixCraft 的創建者，經驗豐富的系統管理員，也是 Linux / Unix shell 腳本的培訓師。他曾與全球客户以及IT、教育、國防和太空研究以及非營利部門等多個行業合作。在 [Twitter][9]、[Facebook][10]、[Google +][11] 上關注他。通過",-1)),o(t,{href:"https://www.cyberciti.biz/atom/atom.xml"},{default:n(()=>[...i[1]||(i[1]=[e("RSS/XML 訂閲",-1)])]),_:1}),i[3]||(i[3]=e("獲取最新的系統管理、Linux/Unix 以及開源主題教程。",-1))]),i[19]||(i[19]=a("hr",null,null,-1)),a("p",null,[i[5]||(i[5]=e("via: ",-1)),o(t,{href:"https://www.cyberciti.biz/faq/how-to-reload-vimrc-file-without-restarting-vim-on-linux-unix/"},{default:n(()=>[...i[4]||(i[4]=[e("https://www.cyberciti.biz/faq/how-to-reload-vimrc-file-without-restarting-vim-on-linux-unix/",-1)])]),_:1})]),a("p",null,[i[9]||(i[9]=e("作者：",-1)),o(t,{href:"https://www.cyberciti.biz/"},{default:n(()=>[...i[6]||(i[6]=[e("Vivek Gite",-1)])]),_:1}),i[10]||(i[10]=e(" 譯者：",-1)),o(t,{href:"https://github.com/geekpi"},{default:n(()=>[...i[7]||(i[7]=[e("geekpi",-1)])]),_:1}),i[11]||(i[11]=e(" 校對：",-1)),o(t,{href:"https://github.com/wxy"},{default:n(()=>[...i[8]||(i[8]=[e("wxy",-1)])]),_:1})]),a("p",null,[i[14]||(i[14]=e("本文由 ",-1)),o(t,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...i[12]||(i[12]=[e("LCTT",-1)])]),_:1}),i[15]||(i[15]=e(" 原創編譯，",-1)),o(t,{href:"https://linux.cn/"},{default:n(()=>[...i[13]||(i[13]=[e("Linux中國",-1)])]),_:1}),i[16]||(i[16]=e(" 榮譽推出",-1))])])}const k=r(p,[["render",m]]);export{w as __pageData,k as default};
